// Build one WF-51 advisory-nudge payload per matching consultation.
// Skips the empty 0-row aggregate item and any row missing channel/user.
// Returns [] when no matches so the downstream Call WF-51 (mode=each) fires zero times.
const out = [];
for (const item of $input.all()) {
  const r = item.json || {};
  if (!r.slack_channel_id || !r.user_id) continue;
  const name = r.user_name || 'the customer';
  const hrs = (r.hours_until_close != null) ? r.hours_until_close : 0;
  const messageText =
    '⏳ Heads-up: ' + name + "'s free-reply window closes in ~" + hrs + 'h. ' +
    'Reply on WhatsApp within the window to answer for free in plain text — ' +
    'after it closes, your reply goes out as a template. Ignore this if you are done.';
  out.push({ json: {
    channelId: r.slack_channel_id,
    messageText: messageText,
    userId: r.user_id,
    consultationId: (r.consultation_id != null) ? r.consultation_id : null
  }});
}
return out;
